# ==============================================================================# IOTEC MISSION CONTROL# 013_API_CORE.py# ==============================================================================import sqlite3import jsonfrom pathlib import Pathfrom datetime import datetimeROOT = Path(__file__).resolve().parentDB = ROOT / "MISSION_CONTROL" / "database" / "mission_control.db"conn = sqlite3.connect(DB, timeout=30)conn.row_factory = sqlite3.Rowcur = conn.cursor()

cur.execute("PRAGMA journal_mode=WAL")
cur.execute("PRAGMA synchronous=NORMAL")
cur.execute("PRAGMA busy_timeout=30000")cur.execute("""CREATE TABLE IF NOT EXISTS api_requests(    id INTEGER PRIMARY KEY AUTOINCREMENT,    timestamp TEXT,    endpoint TEXT,    method TEXT,    status INTEGER,    response_time REAL)""")conn.commit()def api_status():    cur.execute("SELECT COUNT(*) total FROM missions")    missions = cur.fetchone()["total"]    cur.execute("SELECT COUNT(*) total FROM system_logs")    logs = cur.fetchone()["total"]    cur.execute("SELECT COUNT(*) total FROM maestro_history")    maestro = cur.fetchone()["total"]    cur.execute(        """        INSERT INTO api_requests(            timestamp,            endpoint,            method,            status,            response_time        )        VALUES(?,?,?,?,?)        """,        (            datetime.now().isoformat(),            "/api/status",            "GET",            200,            0.001        )    )    conn.commit()    return {        "status":"ONLINE",        "version":"1.0.0",        "missions":missions,        "logs":logs,        "maestro_history":maestro,        "database":"CONNECTED"    }print("="*80)print("API CORE")print("="*80)print(json.dumps(api_status(),indent=4,ensure_ascii=False))print("="*80)conn.close()

